static void gemv(float *y, const float *Wm, const float *xv, int in, int out){
  for(int o=0;o<out;o++) y[o]=0.f;
  for(int i=0;i<in;i++){ float xi=xv[i]; const float *w=Wm+(size_t)i*out;
    for(int o=0;o<out;o++) y[o]+=xi*w[o]; }
}
```

