```c
static void ln(float *y, const float *xv, const float *g, const float *b, int n){
  float m=0.f; for(int i=0;i<n;i++) m+=xv[i]; m/=n;
  float v=0.f; for(int i=0;i<n;i++){ float d=xv[i]-m; v+=d*d; } v/=n;
  float r=1.f/sqrtf(v+1e-5f);
  for(int i=0;i<n;i++) y[i]=(xv[i]-m)*r*g[i]+b[i];
}
```

