static void attn(float *o, const float *q, const float *kc, const float *vc, int t){
  // kc, vc point to layer slice: kc[s*E + j]
  for(int hd=0;hd<H;hd++){
    const float *qh=q+hd*D;
    float mx=-1e30f;
    for(int s=0;s<=t;s++){
      const float *ks=kc+(size_t)s*E+hd*D;
      float d=0.f; for(int j=0;j<D;j++) d+=qh[j]*ks[j];
      sc[s]=d*0.125f; mx=sc[s]>mx?sc[s]:mx;
    }
    float sum=0.f;
    for(int s=0;s<=t;s++){ sc[s]=expf(sc[s]-mx); sum+=sc[s]; }
    for(int s=0;s<=t;s++) sc[s]/=sum;
    float *oh=o+hd*D;
    for(int j=0;j<D;j++) oh[j]=0.f;
    for(int s=0;s<=t;s++){
      float p=sc[s]; const float *vs=vc+(size_t)s*E+hd*D;
      for(int j=0;j<D;j++) oh[j]+=p*vs[j];
    }
  }
}
```

