```c
int n = initial length;
while(n > 1){
  int best=-1, best_rank=INT_MAX, best_i=-1;
  for(int i=0;i<n-1;i++){
    int r = pair_lookup(seq[i], seq[i+1]); // returns merge index or -1
    if(r>=0 && r<best_rank){ best_rank=r; best_i=i; }
  }
  if(best_i<0) break;
  // merge seq[best_i], seq[best_i+1] into new tid = 256+best_rank
  seq[best_i] = 256+best_rank;
  for(int i=best_i+1;i<n-1;i++) seq[i]=seq[i+1];
  n--;
}
```
