// tokenize input string into token ids
static int tokenize(const unsigned char *s, int n, int *out){
  int wo[4096], wl[4096], nw=pretok(s,n,wo,wl);
  int cnt=0;
  for(int w=0;w<nw;w++){
    // convert word bytes to tids
    int seq[256], nn=0;
    for(int i=0;i<wl[w];i++){
      int b=s[wo[w]+i];
      seq[nn++]=base_id[b];
    }
    // BPE
    while(nn>1){
      int best=-1, bri=1<<30, bi=-1;
      for(int i=0;i<nn-1;i++){ int r=pget(seq[i],seq[i+1]); if(r>=0&&r<bri){bri=r;bi=i;} }
      if(bi<0) break;
      seq[bi]=256+bri;
      for(int i=bi+1;i<nn-1;i++) seq[i]=seq[i+1];
      nn--;
    }
    for(int i=0;i<nn;i++) out[cnt++]=seq[i];
  }
  return cnt;
}
```

